import ipaddress

def repair_resolver(text,approved_ip,expected_old):
    address=ipaddress.ip_address(approved_ip)
    if address.version!=4 or address.is_loopback or address.is_unspecified or address.is_multicast or address.is_link_local or not address.is_private:raise ValueError('approved private peer resolver IPv4 required')
    lines=text.splitlines(keepends=True)
    old=[line.split()[1] for line in lines if line.split() and line.split()[0]=='nameserver' and len(line.split())>=2]
    if not old or old!=expected_old or any(not ipaddress.ip_address(value).is_loopback for value in old):raise ValueError('stale or non-loopback source resolver list')
    result=[];written=False
    for line in lines:
        if line.split() and line.split()[0]=='nameserver':
            if not written:result.append('nameserver '+str(address)+'\n');written=True
        else:result.append(line)
    return ''.join(result)
```

